        acts: [save("venom:breath", { activation: "special", condition: "Вместо одной атаки действия атака", consume: [FOCUS(2)], range: 30, count: 1, affects: "creature", ability: "con", dc: "wis", damage: [dmg("3d@scale.monk.die.faces", "poison")], onSave: "half" })]
